// @name JSX: Counter
// @background #1e1b4b
// @refresh 3600
// The smallest interactive UI: onClick changes a number, active: darkens the
// button under the finger, and frameos.remember keeps the count.
let count = null
const load = () => {
  if (count === null) count = frameos.recall('count') ?? 0
}
const set = (n) => { count = n; frameos.remember('count', n) }

const Sign = ({ d }) => (
  <svg className="w-14 h-14 text-white" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3} strokeLinecap="round">
    <path d={d} />
  </svg>
)

export function get(app) {
  load()
  return (
    <div className="flex flex-col items-center justify-center gap-6 bg-indigo-950 text-white">
      <span className="text-lg uppercase text-indigo-300 font-semibold">Tap counter</span>
      <span className="text-9xl font-bold">{`${count}`}</span>
      <div className="flex items-center gap-6">
        <div className="w-28 h-28 rounded-full flex items-center justify-center bg-rose-500 active:bg-rose-700" onClick={() => set(count - 1)}>
          <Sign d="M5 12h14" />
        </div>
        <div className="px-5 py-3 rounded-xl bg-white/10 text-lg text-slate-300 active:bg-white/30" onClick={() => set(0)}>Reset</div>
        <div className="w-28 h-28 rounded-full flex items-center justify-center bg-emerald-500 active:bg-emerald-700" onClick={() => set(count + 1)}>
          <Sign d="M12 5v14M5 12h14" />
        </div>
      </div>
      <span className="text-sm text-slate-500">Hold the top button for the next example</span>
    </div>
  )
}
